/* Mønstre med mal null bygges her, fordi rekkefølgen på delene skifter. */
(function(){
  var M = window.MEG_SPRAK.MONSTER, T = window.MEG_SPRAK.TERM;
  function t(s){ return window.MegSprak ? window.MegSprak.t(s) : s; }
  var VINKEL = {"konjunksjon": "conjunction", "sekstil": "sextile", "kvadrat": "square", "trigon": "trine", "opposisjon": "opposition"};
  var F = {
    "regnes som en tid": function(x){ return (x[2] === "starte og bygge opp" ? "A waxing moon is seen as a time to start and build up." : "A waning moon is seen as a time to clear up and finish.") + " The Moon in " + (T[x[3]] || x[3]) + " is linked with " + t(x[4]) + "." + (x[5] ? " When " + (T[x[5]] || x[5]) + " is retrograde, tradition says to " + t(x[6]) + "." : ""); },
    "· (.+?)(?: ·": function(x){ var kind = {"Fødsel":"Birth","Bryllup":"Wedding","Flytting":"Moving house","Første jobb":"First job","Barn født":"Child born","Annet":"Other"}[x[4]] || x[4]; return (T[x[2]] || x[2]) + " " + x[1] + ", " + x[3] + " · " + kind + (x[5] ? " · " + x[5] + " years" : ""); },
    "(Morgensang|Kveldssang)": function(x){ return (x[1] === "Morgensang" ? "Morning song" : "Evening song") + " for " + x[2] + " · " + x[3]; },
    "^Sola står": function(x){ return "The Sun is " + x[1] + "° from where your Sun was at birth (" + (VINKEL[x[2]] || x[2]) + "), Sun in " + (T[x[3]] || x[3]) + " " + x[4] + "°."; },
    "Du er logget inn": function(x){ return "You are logged in" + (x[2] ? " as " + x[2] : "") + ". Your name and date of birth come from the Member portal. The plan, dinners and interests are your own. The questions and groups are still examples."; },
    "^(\\S+) står": function(x){ return (T[x[1]] || x[1]) + " is " + x[2] + "° from where your Sun was at birth (" + (VINKEL[x[3]] || x[3]) + "), " + t(x[4]) + "."; }
  };
  M.forEach(function(m, i){
    if(m[1] !== null){ return; }
    var src = m[0].source;
    Object.keys(F).forEach(function(k){ if(M[i][2] == null && src.indexOf(k) !== -1){ M[i] = [m[0], null, F[k]]; } });
  });
})();
